fn v50_fold_dive_episode(&mut self, _version, _tps, aborted: bool, end_reason: u8)

// --- 1단계: 헛다이브(abandon) 집계  (src 131~140) ---
131: if let Some(ep) = self.v50_dive_ep_live.as_ref() {          // handler+0x570 태그 != -1
       // 컴파일러가 아래 139줄 조건의 첫 항을 131줄 분기로 끌어올림:
       //   %11 = is_some && (ep.in_range_ticks == 0)
138:   let team_hold_zero = (ep.team_holder_ticks == 0);
139:   if ep.in_range_ticks == 0 && team_hold_zero && end_reason != 7 {
140:     self.last_dive_abandon_tick = max(self.last_dive_abandon_tick, ep.last_tick);  // llvm.umax.i64, RMW
       }
     }
     // 위 조건이 안 맞으면 아무것도 안 하고 2단계로 (조기 return 없음)

// --- 2단계: 현재 플랜 이름으로 end_plan 코드 산출  (src 145~153) ---
145: let n: String = self.plan.get_name();       // plan = handler+0x5e8 (BigPlan 384B)
146: let end_plan: u8 =
          if n.starts_with("PassiveLine")        { 1 }
147:  else if n.starts_with("PassiveJungle")      { 2 }
148:  else if n.starts_with("LineGank")           { 3 }
149:  else if n.contains("Epic")                  { 4 }
150:  else if n.contains("Serpen")                { 5 }
151:  else if n.starts_with("ActiveRecall") || n.starts_with("Recall") { 6 }
152:  else if n.starts_with("Battle")             { 7 }
153:  else if n.contains("Nexus")                 { 8 } else { 9 };
     // 검사 순서 = IR 블록 순서 그대로(먼저 걸린 것이 이김). starts_with 는 str::Pattern::is_prefix_of,
     // contains 는 str::contains(=Pattern::is_contained_in) 로 인라인됨. 둘 다 IR 에는 invoke 로 나온다.
155: drop(n);

// --- 3단계: live 슬롯을 take 해서 에피소드 벡터에 push  (src 156~170) ---
156: let taken = mem::replace(&mut self.v50_dive_ep_live, None);   // 필드들을 먼저 다 로드한 뒤 태그에 -1 저장
     if taken.is_none() { return; }                                // 태그 원본값 == -1 이면 즉시 종료
157:   if self.v50_dive_episodes.len == cap { RawVec::grow_one(); }  // Vec::push 인라인
       let e = &mut ptr[len];   // 원소 104B
       e.max_catch_break    = ep.max_catch_break;    // +0   <- live+0x88
       e.uncatch_total      = ep.uncatch_total;      // +8   <- live+0x90
       e.start_tick         = ep.start_tick;         // +16  <- live+0x10
       e.end_tick           = ep.last_tick;          // +24  <- live+0x18  (이름이 바뀜)
       e.ep_ticks           = ep.ep_ticks;           // +32
       e.in_range_ticks     = ep.in_range_ticks;     // +40
       e.holder_ticks       = ep.holder_ticks;       // +48
       e.team_holder_ticks  = ep.team_holder_ticks;  // +56
       e.minion_cover_ticks = ep.minion_cover_ticks; // +64
       e.soaked_hp          = ep.soaked_hp;          // +72
       e.start_race_adv     = ep.start_race_adv;     // +80 (i32)
       e.target_pos         = ep.target_pos;         // +84 (i32, Position)
167:   e.abort_src          = if aborted { self.v50_dive_ep_abort_src } else { 0 };  // +88, handler+0x1811
       e.start_model        = ep.start_model;        // +89
       e.start_na           = ep.start_na;           // +90
       e.start_ne           = ep.start_ne;           // +91
       e.start_tgt_hp       = ep.start_tgt_hp;       // +92
       e.end_reason         = end_reason;            // +93 (인자 그대로)
       e.end_plan           = end_plan;              // +94 (2단계 결과)
       e.tower              = ep.tower;              // +95
       e.start_in_range     = ep.start_in_range & 1; // +96 (bool)
       e.aborted            = aborted as u8;         // +97
       self.v50_dive_episodes.len += 1;
170: }

// 주의: live 의 gap_ticks(live+0x50) 와 prev_holder_hp(live+0x00~0x10) 는 에피소드로 복사되지 않고 버려진다.
